"""Small entry point for the real-time simulation."""

import sys

from cli import parse_args
from state import PhysicsParameters


def main(argv=None) -> int:
    args = parse_args("Real-time circle simulation in an open box.", argv)
    parameters = PhysicsParameters(restitution=args.restitution, dt=args.dt)
    # Help and invalid options finish before the rendering module is imported.
    from rendering import RenderingDependencyError, run_simulation

    try:
        run_simulation(parameters)
    except RenderingDependencyError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"""Run deterministic numerical checks and write headless validation figures."""

import sys

from cli import parse_args
from validation import run_validation


def main(argv=None) -> int:
    args = parse_args("Headless numerical validation and PNG figures.", argv, figures=True)
    try:
        report = run_validation(args.output_dir, args.restitution, args.dt,
                                args.duration, args.bounce_duration)
    except OSError as exc:
        print(f"Cannot write validation evidence: {exc}", file=sys.stderr)
        return 1
    if report["status"] != "passed":
        print(f"Validation FAILED. See {args.output_dir}/results.json and regression_checks.txt.",
              file=sys.stderr)
        for check in report["checks"]:
            if not check["passed"]:
                print(f"  {check}", file=sys.stderr)
        if "exception" in report:
            print(report["exception"], file=sys.stderr)
        return 1
    print(f"Validation passed. Figures and numerical evidence saved in {args.output_dir}.")
    for label, run in zip(("coarse", "fine"), report["free_fall"]):
        row = run["final"]
        print(f"{label}: y={row['y']:.12g} m (expected {row['expected_height']:.12g}); "
              f"vy={row['vy']:.12g} m/s (expected {row['expected_vy']:.12g}); "
              f"signed error={row['signed_error']:.12g} m "
              f"(expected {row['predicted_signed_error']:.12g})")
    for label, run in zip(("selected", "elastic"), report["bouncing"]):
        print(f"{label}: e={run['parameters']['restitution']}, impacts={run['impact_counts']}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"""Shared command-line parsing, independent of physics and rendering."""

import argparse
import math


def finite_number(text: str) -> float:
    """Parse a finite floating-point number with an argparse-friendly error."""
    try:
        value = float(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("must be a number") from exc
    if not math.isfinite(value):
        raise argparse.ArgumentTypeError("must be finite")
    return value


def restitution_value(text: str) -> float:
    value = finite_number(text)
    if not 0.0 <= value <= 1.0:
        raise argparse.ArgumentTypeError("must be between 0 and 1 inclusive")
    return value


def timestep_value(text: str) -> float:
    value = finite_number(text)
    if value <= 0.0:
        raise argparse.ArgumentTypeError("must be greater than zero seconds")
    return value


def parse_args(description: str, argv=None, *, figures=False) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=description,
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    parser.add_argument(
        "--restitution", type=restitution_value, default=0.8,
        help="coefficient of restitution, finite and in [0, 1]",
    )
    parser.add_argument(
        "--dt", type=timestep_value, default=1.0 / 240.0,
        help="fixed physics timestep in seconds, finite and positive (1/240 s by default)",
    )
    if figures:
        parser.add_argument("--output-dir", default="figures", help="directory for PNG and JSON results")
        parser.add_argument("--duration", type=timestep_value, default=1.0,
                            help="free-fall duration in seconds, positive and aligned with dt")
        parser.add_argument("--bounce-duration", type=timestep_value, default=10.0,
                            help="bouncing duration in seconds, positive and aligned with dt")
    args = parser.parse_args(argv)
    if figures:
        from validation import validate_experiments

        try:
            validate_experiments(args.dt, args.duration, args.bounce_duration)
        except ValueError as exc:
            parser.error(str(exc))
    return args
"""Contact-free integration and a complete step with discrete contacts."""

from contacts import ContactRecord, resolve_contacts
from state import Box, CircleState, PhysicsParameters


def step(state: CircleState, parameters: PhysicsParameters) -> None:
    """Advance state in place by one fixed step without resolving contacts."""
    state.vy -= parameters.gravity * parameters.dt
    state.x += state.vx * parameters.dt
    state.y += state.vy * parameters.dt
    state.step_count += 1


def complete_step(
    state: CircleState, parameters: PhysicsParameters, box: Box
) -> list[ContactRecord]:
    """Integrate once, then resolve floor and walls; return contact records."""
    box.validate_for(parameters)  # Reject invalid geometry before mutating state.
    step(state, parameters)
    return resolve_contacts(state, parameters, box)
"""Discrete floor and side-wall contact resolution in SI units."""

from dataclasses import dataclass

from state import Box, CircleState, PhysicsParameters


@dataclass(frozen=True)
class ContactRecord:
    surface: str
    position_correction: tuple[float, float]  # Signed (dx, dy), meters.
    normal_velocity_before: float  # m/s; positive points into allowed region.
    normal_velocity_after: float

    @property
    def is_impact(self) -> bool:
        """True only when this response actually changed normal velocity."""
        return self.normal_velocity_before != self.normal_velocity_after


def resolve_contacts(
    state: CircleState, parameters: PhysicsParameters, box: Box
) -> list[ContactRecord]:
    """Correct contacts in floor/left/right order without advancing time.

    Normal directions are +y at the floor, +x at the left wall, and -x at
    the right wall. Touching counts as contact, even with no velocity change.
    """
    box.validate_for(parameters)
    radius, restitution = parameters.radius, parameters.restitution
    records = []

    if state.y <= radius:
        correction, before = radius - state.y, state.vy
        state.y = radius
        if state.vy < 0:
            state.vy = -restitution * state.vy
        records.append(ContactRecord("floor", (0.0, correction), before, state.vy))

    if state.x <= radius:
        correction, before = radius - state.x, state.vx
        state.x = radius
        if state.vx < 0:
            state.vx = -restitution * state.vx
        records.append(ContactRecord("left", (correction, 0.0), before, state.vx))

    right = box.width - radius
    if state.x >= right:
        correction, before = right - state.x, -state.vx
        state.x = right
        if state.vx > 0:
            state.vx = -restitution * state.vx
        records.append(ContactRecord("right", (correction, 0.0), before, -state.vx))

    return records
"""Small physics data structures in meters, seconds, and kilograms."""

from dataclasses import dataclass
import math


def _finite(name: str, value: float) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} must be a finite number")
    if not math.isfinite(value):
        raise ValueError(f"{name} must be a finite number")


@dataclass(frozen=True)
class PhysicsParameters:
    radius: float = 0.2
    mass: float = 1.0
    gravity: float = 9.81
    restitution: float = 0.8
    dt: float = 1.0 / 240.0

    def __post_init__(self) -> None:
        for name in ("radius", "mass", "gravity", "restitution", "dt"):
            _finite(name, getattr(self, name))
        for name in ("radius", "mass", "dt"):
            if getattr(self, name) <= 0:
                raise ValueError(f"{name} must be positive")
        if self.gravity < 0:
            raise ValueError("gravity must be nonnegative")
        if not 0 <= self.restitution <= 1:
            raise ValueError("restitution must be in [0, 1]")


@dataclass(frozen=True)
class Box:
    width: float = 4.0
    height: float = 3.0

    def __post_init__(self) -> None:
        for name in ("width", "height"):
            _finite(name, getattr(self, name))
            if getattr(self, name) <= 0:
                raise ValueError(f"{name} must be positive")

    def validate_for(self, parameters: PhysicsParameters) -> None:
        """Check geometry against the selected radius, without constraining state."""
        if min(self.width, self.height) <= 2 * parameters.radius:
            raise ValueError("box width and height must exceed the circle diameter")


@dataclass
class CircleState:
    x: float = 1.0
    y: float = 2.0
    vx: float = 1.5
    vy: float = 0.0
    step_count: int = 0

    def __post_init__(self) -> None:
        self.validate()

    def validate(self) -> None:
        """Allow any finite position, including penetration and above-box states."""
        for name in ("x", "y", "vx", "vy"):
            _finite(name, getattr(self, name))
        if type(self.step_count) is not int or self.step_count < 0:
            raise ValueError("step_count must be a nonnegative integer")

    def time(self, parameters: PhysicsParameters) -> float:
        """Elapsed seconds; keep the same fixed dt throughout a trajectory."""
        return self.step_count * parameters.dt

